import{_ as a,o as r,c as t,a2 as i}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Calendar Ledger","description":"","frontmatter":{},"headers":[],"relativePath":"new-features/calendar-ledger.md","filePath":"new-features/calendar-ledger.md"}'),n={name:"new-features/calendar-ledger.md"};function o(s,e,l,d,c,g){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="calendar-ledger" tabindex="-1">Calendar Ledger <a class="header-anchor" href="#calendar-ledger" aria-label="Permalink to &quot;Calendar Ledger&quot;">​</a></h1><p>Tradeboard includes an integrated <strong>Calendar Ledger</strong> designed for active algorithmic traders, quantitative funds, and retail traders to analyze daily performance, track closed-trade P&amp;L, and review trading frequency at a glance.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Calendar Ledger transforms raw transaction logs into an intuitive, color-coded calendar heat map. Rather than sifting through tabular broker statements, traders can immediately identify winning days, drawdown clusters, and trading frequency patterns.</p><h3 id="key-capabilities" tabindex="-1">Key Capabilities <a class="header-anchor" href="#key-capabilities" aria-label="Permalink to &quot;Key Capabilities&quot;">​</a></h3><ul><li><strong>Interactive Monthly Grid</strong>: Full-month calendar view with daily net P&amp;L figures prominently displayed.</li><li><strong>Dynamic Color Coding</strong>: <ul><li>🟢 <strong>Profitable Days</strong>: Highlighted in soft green with positive net returns.</li><li>🔴 <strong>Loss Days</strong>: Highlighted in soft red with negative net drawdown.</li><li>⚪ <strong>Breakeven / Inactive Days</strong>: Neutral display when no closed positions exist.</li></ul></li><li><strong>Detailed Day Inspection</strong>: Clicking on any date opens an itemized modal of all executions for that trading session, including symbol, instrument type, entry/exit price, trade duration, and realized P&amp;L.</li><li><strong>Multi-Currency Support</strong>: Seamless formatting in Indian Rupees (<strong>₹</strong>) for Indian stock brokers and US Dollars (<strong>$</strong>) for crypto exchanges.</li><li><strong>Aggregate Performance Summary</strong>: <ul><li>Gross Realized P&amp;L</li><li>Net Profit Factor</li><li>Winning Days vs. Losing Days ratio</li><li>Average Daily Gain / Average Daily Loss</li></ul></li></ul><hr><h2 id="accessing-the-calendar-ledger" tabindex="-1">Accessing the Calendar Ledger <a class="header-anchor" href="#accessing-the-calendar-ledger" aria-label="Permalink to &quot;Accessing the Calendar Ledger&quot;">​</a></h2><ol><li>Log into your <strong>Tradeboard</strong> dashboard.</li><li>From the main navigation sidebar, select <strong>Calendar Ledger</strong> (under Analytics / Dashboard).</li><li>Use the month/year picker at the top to navigate between different historical periods.</li><li>Click any active trading day to inspect trade logs and execution timestamps.</li></ol><hr><h2 id="integration-with-sandbox-live-accounts" tabindex="-1">Integration with Sandbox &amp; Live Accounts <a class="header-anchor" href="#integration-with-sandbox-live-accounts" aria-label="Permalink to &quot;Integration with Sandbox &amp; Live Accounts&quot;">​</a></h2><p>The Calendar Ledger works across both live broker accounts and the <strong>Tradeboard Sandbox</strong>:</p><ul><li><strong>Sandbox Mode</strong>: Perfect for forward-testing automated bots over weeks to evaluate consistency without risking real capital.</li><li><strong>Live Trading</strong>: Syncs directly with broker trade logs to ensure an accurate post-market journal.</li></ul><div class="tip custom-block"><p class="custom-block-title">PRO TIP</p><p>Review your Calendar Ledger weekly to identify if specific days of the week (e.g., expiry Thursdays) suffer from oversized drawdowns, and adjust your Strategy RMS max-drawdown rules accordingly.</p></div>',15)])])}const p=a(n,[["render",o]]);export{u as __pageData,p as default};
